package br.com.weg.workshop.post.domain; import br.com.weg.workshop.user.domain.UserEntity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="post_like",schema="workshop") @IdClass(PostLikeId.class) public class PostLike { @Id @ManyToOne @JoinColumn(name="post_id") private Post post; @Id @ManyToOne @JoinColumn(name="user_id") private UserEntity user; @Column(nullable=false) private Instant createdAt; protected PostLike(){} public PostLike(Post post,UserEntity user){this.post=post;this.user=user;createdAt=Instant.now();} }
